extends Node3D

func _ready():
	var cam = get_node_or_null("World/SourceViewport/SourceCamera")
	if cam:
		cam.current = true
		cam.make_current()

func set_camera_pose(pos: Vector3, basis: Basis) -> void:
	var cam = get_node_or_null("World/SourceViewport/SourceCamera")
	var vp = get_node_or_null("World/SourceViewport")
	if cam and vp:
		# Camera is inside the viewport but the viewport node's global_transform
		# represents the parent chain. Setting the local transform such that the
		# global transform is the target.
		var target = Transform3D(basis, pos)
		# In Godot 4, the SubViewport's children are not in the main scene tree,
		# so global_transform/position cannot be set directly (is_inside_tree error).
		# We set the local transform based on the viewport node's global transform.
		var vp_global = vp.global_transform
		cam.transform = vp_global.affine_inverse() * target
EOF
